import fs from 'node:fs';
import path from 'node:path';

const root = path.dirname(new URL(import.meta.url).pathname);
const tracksDir = path.join(root, 'tracks');
fs.mkdirSync(tracksDir, { recursive: true });

const T = {
  top: 'international_continental_top',
  nat: 'mature_national',
  ind: 'historic_independent_invitation',
};

const rows = [];
const add = (region, tier, iso, city, venue, series, year, round, venueType, variant, route, publisher, url, sourceTier, score, tags = [], extra = {}) => {
  const slug = s => s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 32).replace(/-$/,'');
  const id = extra.id || `${iso.toLowerCase()}-${slug(city)}-${slug(venue)}-${slug(series)}-${year}`;
  rows.push({
    track_id: id, display_name: extra.display || `${series} ${year} — ${venue}`, event_name: extra.event || `${series} ${round}`,
    series, event_tier: tier, event_year: year, round, venue_name: venue, city,
    country_or_region: extra.country, iso_country_code: iso, atlas_region: region, venue_type: venueType,
    course_variant: variant, direction: extra.direction || 'start-to-finish sequence shown by the cited competition run; open judged course, so whole-lap CW/CCW is not applicable',
    course_segment: extra.segment || 'event-specific judged segment shown in the cited competition source; not the venue full-lap map',
    start_description: extra.start || 'marked/staged competition start visible in the cited run',
    finish_description: extra.finish || 'end of the judged sequence visible in the cited run',
    initiation_description: extra.initiation || 'first judged initiation visible after the acceleration zone; exact marker coordinates require the production review pass',
    judged_features: extra.features || 'only features visibly marked or repeatedly demonstrated in the cited event source; no inferred clip points are authorized',
    route_source_title: route, route_source_publisher: publisher, route_source_url: url, route_source_tier: sourceTier,
    route_source_ref: extra.ref || (url.includes('youtube.com') ? 'full programme or complete clip; repeated complete judged runs; exact frame timecode to be pinned during blind review' : 'named event/course section on page'),
    second_route_title: extra.route2Title || null, second_route_publisher: extra.route2Publisher || null,
    second_route_url: extra.route2Url || null, second_route_tier: extra.route2Tier || null,
    second_route_ref: extra.route2Ref || null,
    identity_url: extra.identityUrl || null, identity_title: extra.identityTitle || null,
    selection_score: score, diversity_tags: tags, evidence_status: extra.evidence || 'source-threshold-met',
    selection_status: extra.selection || 'selected', backup_rank: extra.backupRank || null,
    replacement_for: extra.replacementFor || null, evidence_conflicts: extra.conflicts || null,
    confidence_notes: extra.notes || 'Course direction is evidenced by the run sequence; compass bearing and marker coordinates remain a production-stage transcription task.',
    redraw_basis: 'Reconstruct factual topology from the competition run plus a separate OSM/venue context map; do not trace either source artwork.',
    source_licenses: 'Competition media: reference-only; OSM context: ODbL attribution required if geometry is derived.',
    derivative_risk: extra.risk || 'medium', researcher: 'Codex research execution 2026-08-17', reviewer: null,
    production_clearance: 'pending-independent-blind-review', status: 'research-complete', version: '1.0.0',
  });
};

