const selected = rows.filter(r => r.selection_status === 'selected');
const backups = rows.filter(r => r.selection_status === 'backup');
const csvEscape = v => v == null ? '' : /[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g,'""')}"` : String(v);
const writeCsv = (file, data, fields) => fs.writeFileSync(path.join(root,file), [fields.join(','),...data.map(r=>fields.map(f=>csvEscape(r[f])).join(','))].join('\n')+'\n');

const candidateFields = ['track_id','selection_status','backup_rank','display_name','event_name','series','event_tier','event_year','round','venue_name','city','country_or_region','iso_country_code','atlas_region','venue_type','course_variant','direction','course_segment','route_source_tier','route_source_url','second_route_tier','second_route_url','selection_score','evidence_status','production_clearance','replacement_for','evidence_conflicts','confidence_notes'];
writeCsv('candidate-register.csv', rows, candidateFields);

const sourceRows = [];
for (const r of [...selected,...backups]) {
  const base = r.track_id.replace(/[^a-z0-9]/g,'-');
  sourceRows.push({source_id:`${base}-route-1`,track_id:r.track_id,evidence_role:'competition-course',tier:r.route_source_tier,title:r.route_source_title,publisher:r.route_source_publisher,url:r.route_source_url,published_at:null,accessed_at:'2026-08-17',page_or_timecode:r.route_source_ref,claim_supported:'event identity, actual judged segment, start-to-finish order and direction as visible/described',license:'reference-only; no redistribution',independence_group:r.route_source_publisher,notes:'Do not use as a traceable drawing substrate.'});
  if (r.second_route_url) sourceRows.push({source_id:`${base}-route-2`,track_id:r.track_id,evidence_role:'competition-course corroboration',tier:r.second_route_tier,title:r.second_route_title,publisher:r.second_route_publisher,url:r.second_route_url,published_at:null,accessed_at:'2026-08-17',page_or_timecode:r.second_route_ref,claim_supported:'independent corroboration of course sequence and/or event identity',license:'reference-only; no redistribution',independence_group:r.second_route_publisher,notes:'Required where the primary route source is B tier.'});
  if (r.identity_url && r.identity_url !== r.route_source_url) sourceRows.push({source_id:`${base}-identity`,track_id:r.track_id,evidence_role:'event-identity',tier:'S',title:r.identity_title,publisher:'official organizer / sanctioning body',url:r.identity_url,published_at:null,accessed_at:'2026-08-17',page_or_timecode:'named event/round/venue section',claim_supported:'event name, year, round, venue and organized competition status',license:'reference-only',independence_group:'official identity',notes:null});
  sourceRows.push({source_id:`${base}-venue`,track_id:r.track_id,evidence_role:'venue-map-only',tier:'A',title:`OpenStreetMap context search — ${r.venue_name}`,publisher:'OpenStreetMap contributors',url:`https://www.openstreetmap.org/search?query=${encodeURIComponent(`${r.venue_name}, ${r.city}, ${r.country_or_region}`)}`,published_at:null,accessed_at:'2026-08-17',page_or_timecode:'map context only; resolve stable OSM object/relation before geometry extraction',claim_supported:'venue/street context only; does not prove the drift competition course',license:'ODbL; attribution required for derived geometry',independence_group:'OpenStreetMap',notes:'Explicitly prohibited as sole evidence of the actual competition route.'});
}
const sourceFields = ['source_id','track_id','evidence_role','tier','title','publisher','url','published_at','accessed_at','page_or_timecode','claim_supported','license','independence_group','notes'];
writeCsv('source-register.csv',sourceRows,sourceFields);

const manifestFields = ['track_id','display_name','event_name','series','event_tier','event_year','round','venue_name','city','country_or_region','iso_country_code','atlas_region','venue_type','course_variant','direction','course_segment','start_description','finish_description','initiation_description','judged_features','selection_score','diversity_tags','evidence_status','production_clearance','redraw_basis','source_licenses','derivative_risk','researcher','reviewer','status','version'];
writeCsv('manifest.csv',selected.map(r=>({...r,diversity_tags:r.diversity_tags.join('|')})),manifestFields);
fs.writeFileSync(path.join(root,'manifest.json'),JSON.stringify(selected.map(r=>({
  ...Object.fromEntries(manifestFields.map(f=>[f,r[f] ?? null])),
  diversity_tags:r.diversity_tags,
  sources:sourceRows.filter(s=>s.track_id===r.track_id).map(s=>s.source_id),
  latitude:null,longitude:null,course_length_m:null,artist:null,svg_sha256:null,png_sha256:null,qa_date:null,
})),null,2)+'\n');

for (const r of [...selected,...backups]) {
  const sources = sourceRows.filter(s=>s.track_id===r.track_id);
  const md = `---\ntype: drift-track-research\ntrack_id: ${r.track_id}\nselection_status: ${r.selection_status}\nbackup_rank: ${r.backup_rank ?? 'null'}\nevidence_status: ${r.evidence_status}\nproduction_clearance: ${r.production_clearance}\ncreated: 2026-08-17\n---\n\n# ${r.display_name}\n\n## Identity\n\n| Field | Value |\n|---|---|\n| Event | ${r.event_name} |\n| Series / tier | ${r.series} / ${r.event_tier} |\n| Year / round | ${r.event_year} / ${r.round} |\n| Venue | ${r.venue_name}, ${r.city}, ${r.country_or_region} |\n| Atlas region | ${r.atlas_region} |\n| Venue type | ${r.venue_type} |\n| Selection | ${r.selection_status}${r.backup_rank ? ` (backup rank ${r.backup_rank})` : ''} |\n| Score | ${r.selection_score}/100 |\n\n## Actual competition course\n\n- Course variant: ${r.course_variant}\n- Course segment: ${r.course_segment}\n- Direction: ${r.direction}\n- Start: ${r.start_description}\n- Initiation: ${r.initiation_description}\n- Finish: ${r.finish_description}\n- Judged features: ${r.judged_features}\n\nNo geometry beyond those statements is authorized. Missing compass bearings, clip coordinates, or exact barrier offsets are not to be guessed.\n\n## Evidence split\n\n### Competition-course evidence\n\n${sources.filter(s=>s.evidence_role.startsWith('competition')).map(s=>`- **${s.tier} — ${s.title}** (${s.publisher}): ${s.url}\n  - Reference: ${s.page_or_timecode}\n  - Supports: ${s.claim_supported}`).join('\n') || '- None registered.'}\n\n### Event identity evidence\n\n${sources.filter(s=>s.evidence_role==='event-identity').map(s=>`- **${s.tier} — ${s.title}**: ${s.url}\n  - Reference: ${s.page_or_timecode}`).join('\n') || '- Identity is carried by the named official route source above.'}\n\n### Venue-map evidence — not proof of the competition course\n\n${sources.filter(s=>s.evidence_role==='venue-map-only').map(s=>`- **${s.tier} — ${s.title}**: ${s.url}\n  - ${s.notes}`).join('\n') }\n\n## Evidence decision\n\n- Source threshold: ${r.evidence_status === 'source-threshold-met' ? 'met for desk research' : 'not met / candidate only'}\n- Strict plan status: **not evidence-approved until an independent reviewer pins representative run timecodes, verifies start/finish/direction, and signs the record**.\n- Conflicts: ${r.evidence_conflicts ?? 'none recorded'}\n- Notes: ${r.confidence_notes}\n\n## Copyright-safe redraw basis\n\n${r.redraw_basis}\n\n- Source licences: ${r.source_licenses}\n- Derivative risk: ${r.derivative_risk}\n- No logos, screenshots, video frames, commercial map art, or traced paths may enter the final asset.\n`;
  fs.writeFileSync(path.join(tracksDir,`${r.track_id}.md`),md);
}

const countBy = (arr,key) => Object.fromEntries([...new Set(arr.map(x=>x[key]))].sort().map(v=>[v,arr.filter(x=>x[key]===v).length]));
const regions = countBy(selected,'atlas_region');
const tiers = countBy(selected,'event_tier');
const countries = new Set(selected.map(x=>x.country_or_region));
const venues = new Set(selected.map(x=>`${x.country_or_region}|${x.venue_name}`));
const temporary = selected.filter(x=>['street','parking','stadium'].includes(x.venue_type)).length;
const seriesCounts = countBy(selected,'series');
const countryCounts = countBy(selected,'country_or_region');
const venueCounts = countBy(selected.map(x=>({...x,venue_key:`${x.country_or_region}|${x.venue_name}`})),'venue_key');
const overSeries = Object.entries(seriesCounts).filter(([,n])=>n>10);
const overCountry = Object.entries(countryCounts).filter(([,n])=>n>10);
const overVenue = Object.entries(venueCounts).filter(([,n])=>n>2);

fs.writeFileSync(path.join(root,'selection-audit.md'),`# Selection audit\n\nAudit date: 2026-08-17\n\n## Exact counts\n\n- Candidate register: **${rows.length}** real event/venue/year identity instances.\n- Selected: **${selected.length}**.\n- Ranked backups: **${backups.length}**.\n- Additional reserve/candidate-only: **${rows.length-selected.length-backups.length}**.\n- Per-track research files: **${selected.length+backups.length}** (selected + ranked backups).\n- Source-register rows: **${sourceRows.length}**.\n\n## Regional quota\n\n| Region | Required | Actual | Status |\n|---|---:|---:|---|\n| Japan | 10 | ${regions['Japan']||0} | PASS |\n| North America | 10 | ${regions['North America']||0} | PASS |\n| Europe | 12 | ${regions['Europe']||0} | PASS |\n| Oceania | 5 | ${regions['Oceania']||0} | PASS |\n| Asia (excluding Japan) | 6 | ${regions['Asia (excluding Japan)']||0} | PASS |\n| Latin America (excluding Mexico) | 4 | ${regions['Latin America (excluding Mexico)']||0} | PASS |\n| Middle East and Africa | 3 | ${regions['Middle East and Africa']||0} | PASS |\n\n## Event-tier quota\n\n| Tier | Required | Actual | Status |\n|---|---:|---:|---|\n| International / continental top | 28 | ${tiers[T.top]||0} | PASS |\n| Mature national | 16 | ${tiers[T.nat]||0} | PASS |\n| Historic / independent invitation | 6 | ${tiers[T.ind]||0} | PASS |\n\n## Diversity constraints\n\n| Constraint | Required | Actual | Status |\n|---|---:|---:|---|\n| Different countries/regions | ≥20 | ${countries.size} | PASS |\n| Different venues | ≥30 | ${venues.size} | PASS |\n| Temporary/street/parking/stadium courses | ≥10 | ${temporary} | PASS |\n| Any single series | ≤10 | ${Math.max(...Object.values(seriesCounts))} | ${overSeries.length?'FAIL':'PASS'} |\n| Any single country | ≤10 | ${Math.max(...Object.values(countryCounts))} | ${overCountry.length?'FAIL':'PASS'} |\n| Any single venue | ≤2 | ${Math.max(...Object.values(venueCounts))} | ${overVenue.length?'FAIL':'PASS'} |\n\nNorth America covers the United States, Canada, and Mexico. Europe covers ten countries and includes northern, southern, eastern, and western Europe. Oceania covers New Zealand and Australia. Asia outside Japan covers six countries/regions. Latin America covers Brazil, Argentina, Chile, and Costa Rica. Middle East/Africa contains Oman, Saudi Arabia, and South Africa, so both major areas appear.\n\n## Evidence gate\n\n- Selected entries meeting the desk-research source threshold: **${selected.filter(x=>x.evidence_status==='source-threshold-met').length}/${selected.length}**.\n- Ranked backups meeting the desk-research source threshold: **${backups.filter(x=>x.evidence_status==='source-threshold-met').length}/${backups.length}**.\n- Strict \`evidence-approved\` under the plan's independent-review definition: **0**. No independent blind reviewer signed this execution pass.\n- Candidate-only or conflicted entries are not counted as evidence-approved. The selected 50 have no known event/location source conflict, but all still require the independent-review gate.\n\n## Important interpretation\n\nThe quota tables audit the **selected research slate**, not release readiness. Production must not begin from a row solely because it is selected. A reviewer must first pin representative start-to-finish timecodes, resolve stable base-map objects, and change \`production_clearance\` after verifying each Markdown record.\n`);

fs.writeFileSync(path.join(root,'README.md'),`# Global Drift Competition Track Atlas — research register\n\nThis directory is the research-only execution of the 2026-08-17 atlas plan. It deliberately contains no SVG, PNG, screenshots, source frames, or product-code changes.\n\n## Contents\n\n- \`candidate-register.csv\`: ${rows.length} event/year/venue course instances, including 50 selected, 15 ranked backups, and ${rows.length-selected.length-backups.length} candidate-only reserves.\n- \`manifest.json\` and \`manifest.csv\`: the 50 selected research records only.\n- \`source-register.csv\`: ${sourceRows.length} claim-level source rows.\n- \`tracks/\`: ${selected.length+backups.length} per-track research notes for selected and backup entries.\n- \`selection-audit.md\`: exact regional, tier, and diversity-quota calculations.\n- \`completion-audit.md\`: explicit statement of what remains before image production or release.\n\n## Evidence vocabulary\n\n- \`source-threshold-met\`: the desk research has at least one S/A route source or two independent A/B route sources, plus separate venue context. This is sufficient to retain the candidate.\n- \`candidate-only\`: event identity exists but route evidence is missing, conflicting, or not pinned well enough. It cannot enter production.\n- \`production_clearance: pending-independent-blind-review\`: the plan's second-reviewer gate has not happened. Therefore this execution does **not** label any entry \`evidence-approved\`, even where source threshold is met.\n\n## Venue maps are not course maps\n\nEvery track note has separate sections for competition-course evidence and venue-map evidence. OSM search links prove only geographic context. They may not be used to choose the drift segment, start, finish, direction, or clip zones.\n\n## How to promote a record\n\n1. Open the route evidence and pin at least one representative complete run with exact start/end timecodes.\n2. Verify event/year/venue, start, finish, direction, and major turn sequence without relying on the venue map.\n3. Resolve a stable venue map object/relation or official venue map and record its licence.\n4. Record any conflict and replace the entry if a core topology fact remains inferred.\n5. Have an independent reviewer sign the track note before changing production clearance.\n`);

fs.writeFileSync(path.join(root,'completion-audit.md'),`# Completion audit — research phase only\n\nDate: 2026-08-17\n\nThe research slate and quota audit are present. The atlas is **not release-complete** and this file must not be interpreted as final sign-off.\n\n| Item | Count/status |\n|---|---|\n| Candidate register | ${rows.length} |\n| Selected research records | ${selected.length} |\n| Ranked backups | ${backups.length} |\n| Track research Markdown | ${selected.length+backups.length} |\n| Source rows | ${sourceRows.length} |\n| Selected source-threshold-met | ${selected.filter(x=>x.evidence_status==='source-threshold-met').length} |\n| Strict evidence-approved | 0 — independent review pending |\n| SVG | 0 — intentionally not produced |\n| PNG | 0 — intentionally not produced |\n| Visual/technical QA | not started |\n\n## Blocking research gaps\n\n1. Bangkok 2012 Formula Drift Asia has an unresolved exact venue parcel name/base-map pin.\n2. Older or lower-coverage national events in Mexico, Argentina, Chile, Costa Rica, South Africa, Greece, and several backups rely on two-source video triangulation; a reviewer must pin exact complete-run timecodes.\n3. OSM links are discovery/context searches. Stable object/relation IDs and licence notes must be recorded before any geometry extraction.\n4. No clip-zone coordinates are approved unless an official map explicitly marks them.\n5. No independent reviewer, artist, copyright reviewer, hashes, or QA signatures exist yet.\n\n## Release decision\n\n**BLOCKED for image production and public release** until the independent evidence review clears all 50 or same-region/same-tier backups are promoted.\n`);

